f764bad44c', 2, 'adjective', null, 'average, mediocre', 'Hans karakterer er middel.', 'His grades are average.'), ('gratis', 'word', '5d751d3a-f95d-5485-a52b-77a06b9ebb0e', 1, 'adjective', null, 'free (no charge)', 'Billetten var gratis.', 'The ticket was free.'), ('gribe', 'word', '0f6de1d5-708b-5277-93f4-cb639d37c62e', 1, 'verb', null, 'to grab, to catch', 'Han greb bolden med begge hænder.', 'He caught the ball with both hands.'), ('gribe', 'word', '98b97ccc-b56e-52ba-8947-4bec0e0884b1', 2, 'verb', null, 'to move, to touch (emotionally)', 'Historien greb alle i salen.', 'The story moved everyone in the hall.'), ('lande', 'word', 'eb305b82-42f9-5f60-b671-6c4c3e951606', 1, 'verb', null, 'to land', 'Flyet landede til tiden.', 'The plane landed on time.'), ('styre', 'word', 'fe9068ac-1362-55a9-a090-2b705df26f3c', 1, 'verb', null, 'to steer, to control', 'Han styrer bilen meget sikkert.', 'He steers the car very confidently.'), ('styre', 'word', '70580304-bcd8-5cb3-8577-b2f90488cf2b', 2, 'verb', null, 'to control oneself, to hold back', 'Hun kunne ikke styre sig og lo højt.', 'She could not control herself and laughed loudly.'), ('forestille', 'word', 'cf372306-5b42-5053-be3e-85196b0c5bd0', 1, 'verb', null, 'to imagine', 'Kan du forestille dig livet uden telefon?', 'Can you imagine life without a phone?'), ('forestille', 'word', '7fc3f334-c53a-5f5c-828f-6c6b86c08af6', 2, 'verb', null, 'to introduce (someone to someone)', 'Han forestillede sin ven for familien.', 'He introduced his friend to the family.'), ('udføre', 'word', 'f069670b-13c2-51bf-9575-8970308e53de', 1, 'verb', null, 'to carry out, to perform', 'Arbejderne udførte opgaven hurtigt.', 'The workers carried out the task quickly.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
